import SwiftUI

// MARK: - Data Structures

struct PromptOption: Identifiable, Codable {
    let id: String
    let title: String
    let prompt: String
}

struct PromptCategory: Identifiable {
    let id: String
    let name: String
    let icon: String
    let options: [PromptOption]
    let groupColor: Color

    enum CodingKeys: String, CodingKey {
        case id, name, icon
    }
}

// MARK: - Category Groups

enum CategoryGroup: String, CaseIterable {
    case body = "Body"
    case face = "Face"
    case style = "Style"
    case outfit = "Outfit"
    case camera = "Camera"
    case scene = "Scene"

    var color: Color {
        switch self {
        case .body: return Theme.bodyColor
        case .face: return Theme.faceColor
        case .style: return Theme.styleColor
        case .outfit: return Theme.outfitColor
        case .camera: return Theme.cameraColor
        case .scene: return Theme.sceneColor
        }
    }

    var icon: String {
        switch self {
        case .body: return "figure.stand"
        case .face: return "face.smiling"
        case .style: return "paintpalette"
        case .outfit: return "tshirt"
        case .camera: return "camera"
        case .scene: return "photo.on.rectangle"
        }
    }

    var categories: [PromptCategory] {
        switch self {
        case .body: return [
            AllCategories.bodyPose, AllCategories.torso, AllCategories.arms,
            AllCategories.hands, AllCategories.legs, AllCategories.feet, AllCategories.bodySize
        ]
        case .face: return [
            AllCategories.headPosition, AllCategories.facialExpression,
            AllCategories.eyes, AllCategories.mouth, AllCategories.hair
        ]
        case .style: return [
            AllCategories.aesthetic, AllCategories.lighting, AllCategories.colorPalette,
            AllCategories.texture, AllCategories.mood, AllCategories.photoStyle
        ]
        case .outfit: return [
            AllCategories.outfit, AllCategories.outfitTop, AllCategories.outfitBottom,
            AllCategories.shoes, AllCategories.jewelry, AllCategories.hairAccessories,
            AllCategories.bags, AllCategories.brandDesigner
        ]
        case .camera: return [
            AllCategories.framing, AllCategories.perspective,
            AllCategories.cameraAngle, AllCategories.cameraType
        ]
        case .scene: return [
            AllCategories.background, AllCategories.props
        ]
        }
    }
}

